/**
*@fileaudiodecodingandfilteringusageexample
*@exampledecode_filter_audio.c
*
*Demux,decodeandfilteraudioinputfile,generatearawaudio
*filetobeplayedwithffplay.
*/

#include<unistd.h>

#include<libavcodec/avcodec.h>
#include<libavformat/avformat.h>
#include<libavfilter/buffersink.h>
#include<libavfilter/buffersrc.h>
#include<libavutil/channel_layout.h>
#include<libavutil/mem.h>
#include<libavutil/opt.h>

staticconstchar*filter_descr="aresample=8000,aformat=sample_fmts=s16:channel_layouts=mono";
staticconstchar*player="ffplay-fs16le-ar8000-ac1-";

staticAVFormatContext*fmt_ctx;
staticAVCodecContext*dec_ctx;
AVFilterContext*buffersink_ctx;
AVFilterContext*buffersrc_ctx;
AVFilterGraph*filter_graph;
staticintaudio_stream_index=-1;

staticintopen_input_file(constchar*filename)
{
constAVCodec*dec;
intret;

if((ret=avformat_open_input(&fmt_ctx,filename,NULL,NULL))<0){
av_log(NULL,AV_LOG_ERROR,"Cannotopeninputfile\n");
returnret;
}

if((ret=avformat_find_stream_info(fmt_ctx,NULL))<0){
av_log(NULL,AV_LOG_ERROR,"Cannotfindstreaminformation\n");
returnret;
}

/*selecttheaudiostream*/
ret=av_find_best_stream(fmt_ctx,AVMEDIA_TYPE_AUDIO,-1,-1,&dec,0);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotfindanaudiostreamintheinputfile\n");
returnret;
}
audio_stream_index=ret;

/*createdecodingcontext*/
dec_ctx=avcodec_alloc_context3(dec);
if(!dec_ctx)
returnAVERROR(ENOMEM);
avcodec_parameters_to_context(dec_ctx,fmt_ctx->streams[audio_stream_index]->codecpar);

/*inittheaudiodecoder*/
if((ret=avcodec_open2(dec_ctx,dec,NULL))<0){
av_log(NULL,AV_LOG_ERROR,"Cannotopenaudiodecoder\n");
returnret;
}

return0;
}

staticintinit_filters(constchar*filters_descr)
{
charargs[512];
intret=0;
constAVFilter*abuffersrc=avfilter_get_by_name("abuffer");
constAVFilter*abuffersink=avfilter_get_by_name("abuffersink");
AVFilterInOut*outputs=avfilter_inout_alloc();
AVFilterInOut*inputs=avfilter_inout_alloc();
staticconstintout_sample_rate=8000;
constAVFilterLink*outlink;
AVRationaltime_base=fmt_ctx->streams[audio_stream_index]->time_base;

filter_graph=avfilter_graph_alloc();
if(!outputs||!inputs||!filter_graph){
ret=AVERROR(ENOMEM);
gotoend;
}

/*bufferaudiosource:thedecodedframesfromthedecoderwillbeinsertedhere.*/
if(dec_ctx->ch_layout.order==AV_CHANNEL_ORDER_UNSPEC)
av_channel_layout_default(&dec_ctx->ch_layout,dec_ctx->ch_layout.nb_channels);
ret=snprintf(args,sizeof(args),
"time_base=%d/%d:sample_rate=%d:sample_fmt=%s:channel_layout=",
time_base.num,time_base.den,dec_ctx->sample_rate,
av_get_sample_fmt_name(dec_ctx->sample_fmt));
av_channel_layout_describe(&dec_ctx->ch_layout,args+ret,sizeof(args)-ret);
ret=avfilter_graph_create_filter(&buffersrc_ctx,abuffersrc,"in",
args,NULL,filter_graph);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotcreateaudiobuffersource\n");
gotoend;
}

/*bufferaudiosink:toterminatethefilterchain.*/
buffersink_ctx=avfilter_graph_alloc_filter(filter_graph,abuffersink,"out");
if(!buffersink_ctx){
av_log(NULL,AV_LOG_ERROR,"Cannotcreateaudiobuffersink\n");
ret=AVERROR(ENOMEM);
gotoend;
}

ret=av_opt_set(buffersink_ctx,"sample_formats","s16",
AV_OPT_SEARCH_CHILDREN);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotsetoutputsampleformat\n");
gotoend;
}

ret=av_opt_set(buffersink_ctx,"channel_layouts","mono",
AV_OPT_SEARCH_CHILDREN);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotsetoutputchannellayout\n");
gotoend;
}

ret=av_opt_set_array(buffersink_ctx,"samplerates",AV_OPT_SEARCH_CHILDREN,
0,1,AV_OPT_TYPE_INT,&out_sample_rate);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotsetoutputsamplerate\n");
gotoend;
}

ret=avfilter_init_dict(buffersink_ctx,NULL);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotinitializeaudiobuffersink\n");
gotoend;
}

/*
*Settheendpointsforthefiltergraph.Thefilter_graphwill
*belinkedtothegraphdescribedbyfilters_descr.
*/

/*
*Thebuffersourceoutputmustbeconnectedtotheinputpadof
*thefirstfilterdescribedbyfilters_descr;sincethefirst
*filterinputlabelisnotspecified,itissetto"in"by
*default.
*/
outputs->name=av_strdup("in");
outputs->filter_ctx=buffersrc_ctx;
outputs->pad_idx=0;
outputs->next=NULL;

/*
*Thebuffersinkinputmustbeconnectedtotheoutputpadof
*thelastfilterdescribedbyfilters_descr;sincethelast
*filteroutputlabelisnotspecified,itissetto"out"by
*default.
*/
inputs->name=av_strdup("out");
inputs->filter_ctx=buffersink_ctx;
inputs->pad_idx=0;
inputs->next=NULL;

if((ret=avfilter_graph_parse_ptr(filter_graph,filters_descr,
&inputs,&outputs,NULL))<0)
gotoend;

if((ret=avfilter_graph_config(filter_graph,NULL))<0)
gotoend;

/*Printsummaryofthesinkbuffer
*Note:argsbufferisreusedtostorechannellayoutstring*/
outlink=buffersink_ctx->inputs[0];
av_channel_layout_describe(&outlink->ch_layout,args,sizeof(args));
av_log(NULL,AV_LOG_INFO,"Output:srate:%dHzfmt:%schlayout:%s\n",
(int)outlink->sample_rate,
(char*)av_x_if_null(av_get_sample_fmt_name(outlink->format),"?"),
args);

end:
avfilter_inout_free(&inputs);
avfilter_inout_free(&outputs);

returnret;
}

staticvoidprint_frame(constAVFrame*frame)
{
constintn=frame->nb_samples*frame->ch_layout.nb_channels;
constuint16_t*p=(uint16_t*)frame->data[0];
constuint16_t*p_end=p+n;

while(p<p_end){
fputc(*p&0xff,stdout);
fputc(*p>>8&0xff,stdout);
p++;
}
fflush(stdout);
}

intmain(intargc,char**argv)
{
intret;
AVPacket*packet=av_packet_alloc();
AVFrame*frame=av_frame_alloc();
AVFrame*filt_frame=av_frame_alloc();

if(!packet||!frame||!filt_frame){
fprintf(stderr,"Couldnotallocateframeorpacket\n");
exit(1);
}
if(argc!=2){
fprintf(stderr,"Usage:%sfile|%s\n",argv[0],player);
exit(1);
}

if((ret=open_input_file(argv[1]))<0)
gotoend;
if((ret=init_filters(filter_descr))<0)
gotoend;

/*readallpackets*/
while(1){
if((ret=av_read_frame(fmt_ctx,packet))<0)
break;

if(packet->stream_index==audio_stream_index){
ret=avcodec_send_packet(dec_ctx,packet);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Errorwhilesendingapackettothedecoder\n");
break;
}

while(ret>=0){
ret=avcodec_receive_frame(dec_ctx,frame);
if(ret==AVERROR(EAGAIN)||ret==AVERROR_EOF){
break;
}elseif(ret<0){
av_log(NULL,AV_LOG_ERROR,"Errorwhilereceivingaframefromthedecoder\n");
gotoend;
}

if(ret>=0){
/*pushtheaudiodatafromdecodedframeintothefiltergraph*/
if(av_buffersrc_add_frame_flags(buffersrc_ctx,frame,AV_BUFFERSRC_FLAG_KEEP_REF)<0){
av_log(NULL,AV_LOG_ERROR,"Errorwhilefeedingtheaudiofiltergraph\n");
break;
}

/*pullfilteredaudiofromthefiltergraph*/
while(1){
ret=av_buffersink_get_frame(buffersink_ctx,filt_frame);
if(ret==AVERROR(EAGAIN)||ret==AVERROR_EOF)
break;
if(ret<0)
gotoend;
print_frame(filt_frame);
av_frame_unref(filt_frame);
}
av_frame_unref(frame);
}
}
}
av_packet_unref(packet);
}
if(ret==AVERROR_EOF){
/*signalEOFtothefiltergraph*/
if(av_buffersrc_add_frame_flags(buffersrc_ctx,NULL,0)<0){
av_log(NULL,AV_LOG_ERROR,"Errorwhileclosingthefiltergraph\n");
gotoend;
}

/*pullremainingframesfromthefiltergraph*/
while(1){
ret=av_buffersink_get_frame(buffersink_ctx,filt_frame);
if(ret==AVERROR(EAGAIN)||ret==AVERROR_EOF)
break;
if(ret<0)
gotoend;
print_frame(filt_frame);
av_frame_unref(filt_frame);
}
}

end:
avfilter_graph_free(&filter_graph);
avcodec_free_context(&dec_ctx);
avformat_close_input(&fmt_ctx);
av_packet_free(&packet);
av_frame_free(&frame);
av_frame_free(&filt_frame);

if(ret<0&&ret!=AVERROR_EOF){
fprintf(stderr,"Erroroccurred:%s\n",av_err2str(ret));
exit(1);
}

exit(0);
}
